/* Browser-local Random Forest, fitted preprocessing, held-out evaluation and XAI. */
importScripts('data.js','workflow-core.js');
let model=null;
const normalTokens=new Set(['normal','benign','0','false','legitimate']);
const absent=v=>v===null||v===undefined||String(v).trim()===''||/^(?:nan|[+-]?inf(?:inity)?)$/i.test(String(v).trim());
const numeric=v=>v!==null&&v!==undefined&&String(v).trim()!==''&&Number.isFinite(Number(v));
const median=a=>{a=a.slice().sort((a,b)=>a-b);let m=a.length>>1;return a.length%2?a[m]:(a[m-1]+a[m])/2};
const mode=a=>{let c=new Map;for(let v of a)c.set(v,(c.get(v)||0)+1);return [...c].sort((a,b)=>b[1]-a[1]||String(a[0]).localeCompare(String(b[0])))[0][0]};
function shuffle(a,r){a=a.slice();for(let i=a.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function prepare(rows,features){let schema=[],dropped=[];for(let name of features){let vals=rows.map(x=>x[name]).filter(x=>!absent(x));if(!vals.length){dropped.push(name);continue}let isNum=vals.every(numeric),values=isNum?vals.map(Number):vals.map(String);if(new Set(values).size<2){dropped.push(name);continue}if(isNum){schema.push({name,type:'numeric',typical:median(values),min:Math.min(...values),max:Math.max(...values)})}else{let categories=[...new Set(values)].sort();if(categories.length>30)throw Error('Feature “'+name+'” has over 30 categories. Exclude identifiers and high-cardinality columns.');schema.push({name,type:'categorical',typical:mode(values),categories})}}
 if(!schema.length)throw Error('No usable features remain after training-only constant-column removal.');let dimensions=schema.reduce((n,s)=>n+(s.type==='numeric'?1:s.categories.length),0);if(dimensions>160)throw Error('Too many encoded categories. Select fewer categorical features.');return{schema,dropped,dimensions}}
function transform(row,schema){let x=[];for(let s of schema){if(s.type==='numeric')x.push(numeric(row[s.name])?Number(row[s.name]):s.typical);else{let v=row[s.name];v=absent(v)?s.typical:String(v);for(let cat of s.categories)x.push(v===cat?1:0)}}return x}
function fitTree(X,y,weights,indices,r,depth=0){let total=0,pos=0;for(let i of indices){total+=weights[y[i]];if(y[i])pos+=weights[1]}let p=pos/total;if(depth>=12||indices.length<5||p===0||p===1)return{p};let d=X[0].length,features=shuffle(Array.from({length:d},(_,i)=>i),r).slice(0,Math.max(1,Math.floor(Math.sqrt(d))));let best=null,bestLoss=total*2*p*(1-p);
 for(let f of features){let sorted=indices.map(i=>X[i][f]).sort((a,b)=>a-b);let candidates=new Set;for(let j=1;j<=10;j++){let k=Math.floor(j*sorted.length/11);if(k>0&&sorted[k]!==sorted[k-1])candidates.add((sorted[k]+sorted[k-1])/2)}for(let threshold of candidates){let lw=0,lp=0,ln=0;for(let i of indices)if(X[i][f]<=threshold){lw+=weights[y[i]];lp+=y[i]?weights[1]:0;ln++}let rw=total-lw,rp=pos-lp;if(ln<2||indices.length-ln<2||lw<=0||rw<=0)continue;let loss=2*lp*(1-lp/lw)+2*rp*(1-rp/rw);if(loss<bestLoss-1e-9){bestLoss=loss;best={f,threshold}}}}
 if(!best)return{p};let left=[],right=[];for(let i of indices)(X[i][best.f]<=best.threshold?left:right).push(i);return{...best,left:fitTree(X,y,weights,left,r,depth+1),right:fitTree(X,y,weights,right,r,depth+1)}}
function treeProb(t,x){while(t.f!==undefined)t=x[t.f]<=t.threshold?t.left:t.right;return t.p}
function predictX(x,trees){let p=0;for(let t of trees)p+=treeProb(t,x);return p/trees.length}
function predict(row){return predictX(transform(row,model.schema),model.trees)}
function metrics(y,probs){let tn=0,fp=0,fn=0,tp=0;for(let i=0;i<y.length;i++){let p=probs[i]>=.5;if(y[i])p?tp++:fn++;else p?fp++:tn++}let precision=tp/(tp+fp)||0,recall=tp/(tp+fn)||0,f1=2*tp/(2*tp+fp+fn)||0,normalF1=2*tn/(2*tn+fp+fn)||0;return{accuracy:(tp+tn)/y.length,precision,recall,f1,macroF1:(f1+normalF1)/2,tn,fp,fn,tp,total:y.length}}
function explain(row){let probability=predict(row);return{probability,prediction:probability>=.5?'Suspicious':'Normal',factors:model.schema.map(s=>{let changed={...row,[s.name]:s.typical},replacementProbability=predict(changed);return{name:s.name,value:row[s.name],typical:s.typical,delta:probability-replacementProbability,replacementProbability}}).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta))}}
function train(msg){let {rows,label,features,normalLabels}=msg;let tokens=new Set((normalLabels||[...normalTokens]).map(x=>String(x).trim().toLowerCase()));if(rows.length<20||rows.length>10000)throw Error('Train with 20–10,000 labelled records.');if(!features.length||features.length>40)throw Error('Select between 1 and 40 features.');if(rows.some(x=>String(x[label]??'').trim()===''))throw Error('Every record needs a nonempty target label.');postMessage({type:'stage',stage:'split'});let labels=rows.map(x=>tokens.has(String(x[label]).trim().toLowerCase())?0:1),classes=[[],[]];labels.forEach((y,i)=>classes[y].push(i));if(classes.some(a=>a.length<4))throw Error('Both classes need at least 4 records. Review your Normal label selection.');let r=FlowData.rng(42),trainIds=[],testIds=[];classes.forEach(a=>{let ids=shuffle(a,r),n=Math.max(1,Math.round(a.length*.25));testIds.push(...ids.slice(0,n));trainIds.push(...ids.slice(n))});trainIds=shuffle(trainIds,r);testIds=shuffle(testIds,r);postMessage({type:'stage',stage:'preprocess'});let trainRows=trainIds.map(i=>rows[i]),prep=prepare(trainRows,features),X=trainRows.map(x=>transform(x,prep.schema)),y=trainIds.map(i=>labels[i]),counts=[y.filter(x=>!x).length,y.filter(Boolean).length],weights=counts.map(n=>y.length/(2*n));let trees=[];
 postMessage({type:'stage',stage:'train'});for(let t=0;t<150;t++){let ids=Array.from({length:y.length},()=>Math.floor(r()*y.length));trees.push(fitTree(X,y,weights,ids,r));if((t+1)%15===0)postMessage({type:'progress',progress:Math.round((t+1)/150*78),text:'Training tree '+(t+1)+' of 150'})}
 model={...prep,trees};postMessage({type:'stage',stage:'evaluate'});let testRows=testIds.map(i=>rows[i]),testX=testRows.map(x=>transform(x,prep.schema)),testY=testIds.map(i=>labels[i]),probs=testX.map(x=>predictX(x,trees)),scores=metrics(testY,probs);postMessage({type:'progress',progress:82,text:'Measuring held-out permutation importance'});
 postMessage({type:'stage',stage:'explain'});let importanceRandom=FlowData.rng(4242);let importance=prep.schema.map((s,featureIndex)=>{let drops=[];for(let j=0;j<3;j++){let values=shuffle(testRows.map(x=>x[s.name]),importanceRandom);let pp=testRows.map((x,i)=>predict({...x,[s.name]:values[i]}));drops.push(scores.macroF1-metrics(testY,pp).macroF1)}let mean=drops.reduce((a,b)=>a+b,0)/3;return{name:s.name,importance:mean,std:Math.sqrt(drops.reduce((n,x)=>n+(x-mean)**2,0)/3)}}).sort((a,b)=>b.importance-a.importance);
 let tests=testIds.map((id,i)=>({id:id+1,actual:testY[i]?'Suspicious':'Normal',predicted:probs[i]>=.5?'Suspicious':'Normal',probability:probs[i],values:rows[id]}));let missing=0;for(let row of rows)for(let f of features)if(absent(row[f]))missing++;let seen=new Set,duplicates=0;for(let row of rows){let key=JSON.stringify([...features.map(f=>row[f]??''),String(row[label]).trim().toLowerCase()]);if(seen.has(key))duplicates++;seen.add(key)}
 postMessage({type:'trained',checkpoint:model,result:{scores,importance,tests,schema:prep.schema,dropped:prep.dropped,dimensions:prep.dimensions,trainCount:trainIds.length,testCount:testIds.length,rowCount:rows.length,classCounts:classes.map(x=>x.length),missing,duplicates,label,normalLabels:[...tokens],features:prep.schema.map(x=>x.name),seed:42,trees:150,maxDepth:12,minLeaf:2,permutationRepeats:3,split:'Stratified 75/25',trainedAt:new Date().toISOString()}})}
function restore(m){
 const restored=FlowWorkflow.validateModel(m.checkpoint);model=restored;
 let result=m.result;if(result){postMessage({type:'stage',stage:'evaluate'});if(!Array.isArray(result.tests)||!result.tests.length||result.tests.length>3000)throw Error('Saved experiment has no valid held-out test partition.');let tests=result.tests.map(t=>{if(!Number.isInteger(t.id)||!t.values||!['Normal','Suspicious'].includes(t.actual))throw Error('Invalid saved test record.');let probability=predict(t.values);return{...t,probability,predicted:probability>=.5?'Suspicious':'Normal'}});let y=tests.map(t=>t.actual==='Suspicious'?1:0),scores=metrics(y,tests.map(t=>t.probability)),importanceRandom=FlowData.rng(4242);postMessage({type:'stage',stage:'explain'});let importance=model.schema.map(s=>{let drops=[];for(let j=0;j<3;j++){let values=shuffle(tests.map(t=>t.values[s.name]),importanceRandom);let pp=tests.map((t,i)=>predict({...t.values,[s.name]:values[i]}));drops.push(scores.macroF1-metrics(y,pp).macroF1)}let mean=drops.reduce((a,b)=>a+b,0)/3;return{name:s.name,importance:mean,std:Math.sqrt(drops.reduce((n,x)=>n+(x-mean)**2,0)/3)}}).sort((a,b)=>b.importance-a.importance);result={...result,schema:model.schema,features:model.schema.map(s=>s.name),dimensions:model.dimensions,dropped:model.dropped,trees:150,tests,scores,importance}}
 postMessage({type:'restored',id:m.id,result});
}
function batch(m){
 let quality=FlowWorkflow.batchCheck(m.rows,model.schema),threshold=Number(m.threshold);if(!Number.isFinite(threshold)||threshold<.01||threshold>.99)throw Error('Choose a review threshold from 0.01 to 0.99.');
 let records=m.rows.map((row,i)=>{let probability=predict(row),warnings=[];for(let s of model.schema){let v=row[s.name];if(absent(v))warnings.push(s.name+': imputed');else if(s.type==='categorical'&&!s.categories.includes(String(v)))warnings.push(s.name+': unknown category');else if(s.type==='numeric'&&(Number(v)<s.min||Number(v)>s.max))warnings.push(s.name+': outside training range')}if((i+1)%200===0)postMessage({type:'batch-progress',id:m.id,done:i+1,total:m.rows.length});return{id:i+1,values:row,probability,predicted:probability>=.5?'Suspicious':'Normal',flagged:probability>=threshold,warnings}});
 postMessage({type:'batch-complete',id:m.id,records,quality,threshold});
}
self.onmessage=e=>{try{let m=e.data;if(m.type==='train')train(m);else if(m.type==='restore')restore(m);else if(!model)throw Error('Train or restore a model first.');else if(m.type==='batch')batch(m);else if(m.type==='predict'||m.type==='explain')postMessage({type:m.type,id:m.id,result:explain(m.row)})}catch(err){postMessage({type:'error',id:e.data.id,message:err.message})}};
